<script setup lang="ts">import { onMounted, ref } from "vue"; import { createOrder, listItems, listOrders, listSuppliers, receiveOrder, type Item, type PurchaseOrder, type Supplier } from "../api"; const orders = ref<PurchaseOrder[]>([]); const items = ref<Item[]>([]); const suppliers = ref<Supplier[]>([]); const form = ref({ supplierId: "", itemId: "", quantity: 1, unitCostCents: 0 }); async function load() { [orders.value, items.value, suppliers.value] = await Promise.all([listOrders(), listItems(), listSuppliers()]); } async function save() { await createOrder({ supplierId: form.value.supplierId, lines: [{ inventoryItemId: form.value.itemId, quantity: form.value.quantity, unitCostCents: form.value.unitCostCents }] }); await load(); } async function receive(id: string) { await receiveOrder(id); await load(); } onMounted(load);</script><template><section><header><div><p class="eyebrow">Almacen</p><h1>Ordenes de compra</h1></div></header><div class="operations-grid"><section class="operation-panel"><ul class="operation-list"><li v-for="order in orders" :key="order.id"><div><strong>{{ order.id.slice(0, 8) }}</strong><span>{{ order.status }} - {{ order.lines.length }} lineas</span></div><button v-if="order.status !== 'received'" @click="receive(order.id)">Recibir</button></li></ul><p v-if="!orders.length" class="empty">No hay ordenes de compra.</p></section><form class="operation-panel operation-form" @submit.prevent="save"><h2>Nueva orden</h2><label>Proveedor<select v-model="form.supplierId" required><option disabled value="">Selecciona proveedor</option><option v-for="supplier in suppliers" :key="supplier.id" :value="supplier.id">{{ supplier.name }}</option></select></label><label>Material<select v-model="form.itemId" required><option disabled value="">Selecciona material</option><option v-for="item in items" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>Cantidad<input v-model.number="form.quantity" type="number" min="1" /></label><label>Coste unitario (centimos)<input v-model.number="form.unitCostCents" type="number" min="0" /></label><button>Crear orden</button></form></div></section></template>